\title{Property B and the First-Moment Threshold for\\ Hypergraph Two-Colorability}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
We present a self-contained development of \emph{Property B} --- the
two-colorability of hypergraphs --- through the lens of the probabilistic
method. Our central result is Erd\H{o}s's 1963 first-moment theorem in a sharp
form: a hypergraph in which every edge contains at least $k \ge 1$ vertices and
which has fewer than $2^{k-1}$ edges admits a red/blue vertex coloring with no
monochromatic edge. The argument is a finite union bound over the $2^N$
colorings of an $N$-vertex ground set, resting on two elementary
Boolean-lattice interval counts. We derive the classical $k$-uniform statement,
the extremal-function lower bound $m(k) \ge 2^{k-1}$ in contrapositive form, and
an explicit sharp witness for $k=2$: the triangle is a non-two-colorable
$2$-uniform hypergraph with exactly three edges, yielding $m(2)=3$. We discuss
algorithms, numerical illustrations, connections to Ramsey theory, and
directions toward the Radhakrishnan--Srinivasan improvement and a
Lov\'asz-Local-Lemma variant.
\end{abstract}

\section{Introduction}

A recurring theme in modern combinatorics is that objects with desirable
properties can be shown to exist without being constructed. The
\emph{probabilistic method}, developed and championed by Paul Erd\H{o}s, proves
existence by exhibiting a probability distribution under which the desired
property holds with positive probability: if a random object is ``good'' more
than $0\%$ of the time, at least one good object must exist.

One of the cleanest applications is to \emph{Property B}, the question of
whether the vertices of a hypergraph can be colored with two colors so that no
edge is monochromatic. Named after Felix Bernstein, Property B has been a
proving ground for the probabilistic method for over sixty years. Erd\H{o}s
(1963) showed that any hypergraph whose edges are $k$-element sets and which has
fewer than $2^{k-1}$ edges has Property B. This paper gives a complete,
elementary account of that theorem and its immediate consequences, deliberately
replacing the probabilistic language with an equivalent finite counting
argument that makes every constant explicit.

\paragraph{Contributions.}
\begin{enumerate}
  \item Two Boolean-lattice interval-counting lemmas (superset count and
  disjoint count), each yielding $2^{|G|-|S|}$.
  \item The sharp first-moment theorem: edges of size $\ge k$ and fewer than
  $2^{k-1}$ edges imply two-colorability.
  \item The classical $k$-uniform specialization.
  \item The contrapositive extremal lower bound $m(k) \ge 2^{k-1}$.
  \item An explicit extremal witness establishing $m(2)=3$ via the triangle.
\end{enumerate}

\section{Definitions}

Throughout, $N,k \in \mathbb{N}$ and the vertex set is
$V = \{0,1,\dots,N-1\}$.

\begin{definition}[Hypergraph]
A \emph{hypergraph} on $V$ is a finite family $H$ of subsets of $V$. Each
$e \in H$ is an \emph{edge}. The hypergraph is \emph{$k$-uniform} if $|e|=k$ for
every edge $e$.
\end{definition}

\begin{definition}[Two-coloring]
A \emph{two-coloring} is a subset $R \subseteq V$; the vertices in $R$ are
\emph{red} and those in $V \setminus R$ are \emph{blue}.
\end{definition}

\begin{definition}[Monochromatic edge]
An edge $e$ is \emph{monochromatic} under $R$ if $e \subseteq R$ (all red) or
$e \cap R = \varnothing$ (all blue).
\end{definition}

\begin{definition}[Property B / proper coloring]
A coloring $R$ is \emph{proper} if no edge is monochromatic: for every edge $e$,
$e \not\subseteq R$ and $e \cap R \ne \varnothing$ --- equivalently every edge
contains both a red and a blue vertex. The hypergraph \emph{has Property B} if a
proper coloring exists.
\end{definition}

\begin{definition}[Property B function]
For $k \ge 1$, let $m(k)$ be the least number of edges in a non-two-colorable
$k$-uniform hypergraph; equivalently the largest integer such that every
$k$-uniform hypergraph with fewer than $m(k)$ edges has Property B.
\end{definition}

\section{Boolean-lattice interval counts}

\begin{lemma}[Superset count]\label{lem:sup}
Let $G$ be a finite set and $S \subseteq G$. The number of subsets
$A \subseteq G$ with $S \subseteq A$ equals $2^{|G|-|S|}$.
\end{lemma}
\begin{proof}
The map $A \mapsto A \setminus S$ is a bijection between
$\{A \subseteq G : S \subseteq A\}$ and $\PP(G \setminus S)$. It is injective
because $S \subseteq A,B$ gives $A = (A\setminus S)\cup S$,
$B=(B\setminus S)\cup S$, so $A\setminus S=B\setminus S$ forces $A=B$; it is
surjective because $B \subseteq G\setminus S$ is the image of $B\cup S$. Hence
the count is $|\PP(G\setminus S)| = 2^{|G|-|S|}$.
\end{proof}

\begin{lemma}[Disjoint count]\label{lem:dis}
Let $G$ be a finite set and $S \subseteq G$. The number of subsets
$A \subseteq G$ with $A \cap S = \varnothing$ equals $2^{|G|-|S|}$.
\end{lemma}
\begin{proof}
The complement involution $A \mapsto G\setminus A$ carries
$\{A \subseteq G : A\cap S=\varnothing\}$ bijectively onto
$\{A \subseteq G : S\subseteq A\}$, since $A\cap S=\varnothing$ iff
$S \subseteq G\setminus A$. Apply Lemma~\ref{lem:sup}.
\end{proof}

\section{The first-moment theorem}

\begin{theorem}[Property B, sharp form]\label{thm:main}
Let $H$ be a hypergraph on an $N$-vertex set in which every edge has at least
$k \ge 1$ vertices. If $|H| < 2^{k-1}$, then $H$ has Property B: there exists a
coloring $R$ with $e \not\subseteq R$ and $e \cap R \ne \varnothing$ for every
edge $e$.
\end{theorem}
\begin{proof}
There are exactly $2^N$ colorings, identified with subsets $R \subseteq V$. Call
a coloring \emph{bad for $e$} if $e$ is monochromatic. By Lemma~\ref{lem:sup}
the colorings with $e \subseteq R$ number $2^{N-|e|}$; by Lemma~\ref{lem:dis}
the colorings with $e \cap R = \varnothing$ number $2^{N-|e|}$. Since
$|e| \ge k$ and $x \mapsto 2^{N-x}$ is nonincreasing, each count is at most
$2^{N-k}$, so the colorings bad for $e$ number at most
$2\cdot 2^{N-k} = 2^{N-k+1}$. By sub-additivity, the colorings bad for some edge
number at most
\[
  \sum_{e\in H} 2^{N-k+1} = |H|\cdot 2^{N-k+1} < 2^{k-1}\cdot 2^{N-k+1} = 2^N .
\]
Thus strictly fewer than $2^N$ colorings are bad, so at least one is proper.
\end{proof}

\begin{remark}
The hypothesis bounds edge sizes from below, so Theorem~\ref{thm:main} covers
hypergraphs with edges of mixed sizes, not only uniform ones. The strict
inequality $|H|<2^{k-1}$ is exactly what makes the final estimate strict.
\end{remark}

\begin{corollary}[Classical $k$-uniform Property B]
Every $k$-uniform hypergraph ($k\ge 1$) with fewer than $2^{k-1}$ edges has
Property B.
\end{corollary}
\begin{proof}
All edges have size $k \ge k$; apply Theorem~\ref{thm:main}.
\end{proof}

\begin{corollary}[Membership form]
Under the same hypotheses there is a coloring $R$ such that every edge meets
both $R$ and its complement.
\end{corollary}

\section{The extremal function}

\begin{definition}[Non-two-colorable]
$H$ is \emph{non-two-colorable} if for every coloring $R$ some edge is
monochromatic.
\end{definition}

\begin{theorem}[Extremal lower bound]\label{thm:lower}
If $H$ is non-two-colorable and every edge has at least $k\ge 1$ vertices, then
$|H| \ge 2^{k-1}$; in particular $m(k) \ge 2^{k-1}$.
\end{theorem}
\begin{proof}
Contrapositive of Theorem~\ref{thm:main}: $|H| < 2^{k-1}$ would give Property B.
\end{proof}

\section{A sharp witness: $m(2)=3$}

\begin{definition}[Triangle hypergraph]
Let $T$ be the $2$-uniform hypergraph on $\{0,1,2\}$ with edges $\{0,1\}$,
$\{1,2\}$, $\{0,2\}$, so $|T|=3$.
\end{definition}

\begin{proposition}
$T$ is $2$-uniform, has exactly three edges, and is non-two-colorable.
\end{proposition}
\begin{proof}
Each edge has size $2$ and the three edges are distinct, so $|T|=3$. A
$2$-uniform hypergraph is two-colorable iff it is bipartite; the complete graph
on three vertices contains an odd cycle (itself), hence is not bipartite.
Exhaustively, each of the $2^3=8$ colorings $R\subseteq\{0,1,2\}$ leaves at
least one edge monochromatic, so no proper coloring exists.
\end{proof}

\begin{corollary}
$m(2)\le 3$; combined with Theorem~\ref{thm:lower} and the fact that every graph
with at most two edges is bipartite, $m(2)=3$.
\end{corollary}

For completeness, the smallest non-two-colorable $3$-uniform hypergraph is the
Fano plane (seven lines), giving $m(3)=7 > 2^{3-1}=4$, so the first-moment bound
is not tight for all $k$.

\section{Algorithms}

\begin{description}
  \item[(A) Exhaustive verification.] Enumerate all $2^N$ colorings and test
  each edge; report a proper coloring or declare non-two-colorability.
  Complexity $O(2^N \sum_e |e|)$.
  \item[(B) First-moment feasibility.] Decide the sufficient certificate
  $m < 2^{k-1}$ in $O(1)$.
  \item[(C) Randomized coloring.] Sample $R$ uniformly and accept if proper.
  Under the hypothesis, success probability is at least $1 - m\,2^{-(k-1)} > 0$,
  giving expected trials at most $(1 - m\,2^{-(k-1)})^{-1}$ (a Las Vegas
  algorithm).
\end{description}

\section{Applications and connections}

The template ``color randomly, bound bad events, conclude a good event
survives'' also yields the Ramsey lower bound $R(k,k) > 2^{k/2}$, the existence
of Gilbert--Varshamov codes, and satisfiability guarantees for sparse
constraint systems. The Lov\'asz Local Lemma relaxes the global sparsity
hypothesis to a local one on edge intersections.

\section{Discussion and future work}

\begin{enumerate}
  \item \textbf{Extremal function $m(k)$.} With the lower bound established and
  $m(2)=3$ realized by the triangle, the next targets are $m(3)=7$ (Fano plane)
  and an explicit packaging of $m(k)$ via minimization over non-two-colorable
  configurations.
  \item \textbf{Random / alteration improvement.} Sharpen the lower bound to the
  Radhakrishnan--Srinivasan estimate
  $m(k)=\Omega\!\big(2^k\sqrt{k/\log k}\big)$ via a semi-random recoloring.
  \item \textbf{Local-lemma two-colorability.} A $k$-uniform hypergraph in which
  each edge meets fewer than $2^{k-3}$ others is two-colorable, regardless of
  total edge count.
\end{enumerate}

\section{Conclusion}

Property B crystallizes the probabilistic method into one line: paint at random,
count the failures, and if the failures cannot cover every painting, a success
must exist. The finite counting presentation makes every constant transparent
and the threshold $2^{k-1}$ manifest, while the triangle witness shows the
theory is sharp already at $k=2$.

