\bibitem{E63} P. Erd\H{o}s, \emph{On a combinatorial problem}, Nordisk Mat.
Tidskr. 11 (1963).
\bibitem{E64} P. Erd\H{o}s, \emph{On a combinatorial problem II}, Acta Math.
Acad. Sci. Hungar. 15 (1964).
