"""Verify the two Boolean-lattice interval counts against the closed form."""
from __future__ import annotations
from itertools import combinations
from typing import FrozenSet

def count_supersets(ground: FrozenSet[int], s: FrozenSet[int]) -> int:
    verts = list(ground); total = 0
    for r in range(len(verts) + 1):
        for combo in combinations(verts, r):
            if s <= frozenset(combo): total += 1
    return total

def count_disjoint(ground: FrozenSet[int], s: FrozenSet[int]) -> int:
    verts = list(ground); total = 0
    for r in range(len(verts) + 1):
        for combo in combinations(verts, r):
            if frozenset(combo).isdisjoint(s): total += 1
    return total

def main() -> None:
    for n in range(6):
        ground = frozenset(range(n))
        for sk in range(n + 1):
            s = frozenset(range(sk))
            pred = 2 ** (n - sk)
            assert count_supersets(ground, s) == pred
            assert count_disjoint(ground, s) == pred
    print("All interval counts match 2^(|G|-|S|).")

if __name__ == "__main__":
    main()

