  return m < 2^(k-1)

function UNION_BOUND(N, k, m):
  bad <- m * 2^(N-k+1)      # colorings monochromatic on some edge
  total <- 2^N              # all colorings
  return (bad, total)       # Property B guaranteed when bad < total

