from __future__ import annotations

def first_moment_certificate(k: int, m: int) -> bool:
    """Return True iff Erdos first-moment guarantees Property B:
    edges of size >= k, m edges, and m < 2^(k-1)."""
    if k < 1:
        raise ValueError("k must be >= 1")
    return m < 2 ** (k - 1)

def union_bound(n: int, k: int, m: int) -> tuple[int, int]:
    """Return (upper bound on bad colorings, total colorings) =
    (m * 2^(n-k+1), 2^n)."""
    return m * 2 ** (n - k + 1), 2 ** n

